#pragma once
// Full-width scalar forwarding library: exact 128-bit interval compilation,
// packed FIDX version-2 image construction, packed lookup kernels and the
// exact joint tree/encoding/residency planning search.
#include <algorithm>
#include <cstdint>
#include <cstring>
#include <functional>
#include <map>
#include <stdexcept>
#include <string>
#include <vector>

typedef unsigned __int128 Key;

inline std::string hexkey(Key x) {
    static const char* d = "0123456789abcdef";
    std::string s(32, '0');
    for (int i = 31; i >= 0; --i) { s[i] = d[(unsigned)(x & 15)]; x >>= 4; }
    return s;
}

inline Key parse_key(const std::string& s) {
    if (s.size() != 32) throw std::runtime_error("key width");
    Key v = 0;
    for (size_t i = 0; i < 32; ++i) {
        char c = s[i];
        int d = (c >= '0' && c <= '9') ? c - '0'
              : (c >= 'a' && c <= 'f') ? c - 'a' + 10 : -1;
        if (d < 0) throw std::runtime_error("key digit");
        v = (v << 4) | (Key)(unsigned)d;
    }
    return v;
}

struct entry {
    Key prefix;
    int length;
    int next_hop;
};

// ---------------------------------------------------------------- runs -----
// One RIB version compiled to its unique maximal forwarding runs.  hop -1
// means "no matching route"; the final run always reaches the top of the
// 128-bit domain and no artificial upper endpoint key is emitted.
struct Run { Key start; int hop; };

inline std::vector<Run> compile_runs(const std::vector<entry>& fib) {
    std::vector<entry> r = fib;
    std::sort(r.begin(), r.end(), [](const entry& a, const entry& b) {
        if (a.prefix != b.prefix) return a.prefix < b.prefix;
        return a.length > b.length;              // longer (more specific) first
    });
    std::vector<Key> bounds;
    bounds.push_back((Key)0);
    for (const entry& e : r) {
        bounds.push_back(e.prefix);
        if (e.length > 0) {
            Key size = (Key)1 << (128 - e.length);
            Key last = e.prefix + size - 1;      // no wrap: prefixes are masked
            if (last != ~((Key)0)) bounds.push_back(last + 1);
        }
    }
    std::sort(bounds.begin(), bounds.end());
    bounds.erase(std::unique(bounds.begin(), bounds.end()), bounds.end());
    std::vector<Run> runs;
    std::vector<std::pair<Key, int> > open;      // (exclusive end, hop)
    size_t i = 0, n = r.size();
    for (size_t k = 0; k < bounds.size(); ++k) {
        const Key b = bounds[k];
        while (!open.empty() && open.back().first <= b) open.pop_back();
        while (i < n && r[i].prefix == b) {
            Key end = ~((Key)0);
            if (r[i].length > 0) {
                Key size = (Key)1 << (128 - r[i].length);
                Key last = r[i].prefix + size - 1;
                if (last != ~((Key)0)) end = last + 1;
            }
            open.push_back(std::make_pair(end, r[i].next_hop));
            ++i;
        }
        const int hop = open.empty() ? -1 : open.back().second;
        if (!runs.empty() && runs.back().hop == hop) continue;
        runs.push_back(Run{b, hop});
    }
    if (runs.empty()) runs.push_back(Run{(Key)0, -1});
    return runs;
}

// --------------------------------------------------------------- image -----
const int KW[3] = {16, 8, 4};      // key payload width per encoding mode
const int LN[3] = {4, 8, 16};      // comparison lanes per encoding mode

struct Layout {
    int lo, span, mode, cached;
    std::vector<int> children;     // node indices in breadth-first order
};

inline unsigned rd32(const unsigned char* p) {
    return (unsigned)p[0] | ((unsigned)p[1] << 8) | ((unsigned)p[2] << 16) |
           ((unsigned)p[3] << 24);
}
inline unsigned rd16(const unsigned char* p) {
    return (unsigned)p[0] | ((unsigned)p[1] << 8);
}

inline std::string bytes_hex(const std::vector<unsigned char>& raw) {
    static const char* d = "0123456789abcdef";
    std::string s;
    s.reserve(raw.size() * 2);
    for (size_t i = 0; i < raw.size(); ++i) {
        s.push_back(d[raw[i] >> 4]);
        s.push_back(d[raw[i] & 15]);
    }
    return s;
}

inline std::vector<unsigned char> hex_bytes(const std::string& s) {
    if (s.size() % 2) throw std::runtime_error("hex width");
    std::vector<unsigned char> out;
    out.reserve(s.size() / 2);
    for (size_t i = 0; i < s.size(); i += 2) {
        int hi = (s[i] >= '0' && s[i] <= '9') ? s[i] - '0'
               : (s[i] >= 'a' && s[i] <= 'f') ? s[i] - 'a' + 10 : -1;
        int lo = (s[i+1] >= '0' && s[i+1] <= '9') ? s[i+1] - '0'
               : (s[i+1] >= 'a' && s[i+1] <= 'f') ? s[i+1] - 'a' + 10 : -1;
        if (hi < 0 || lo < 0) throw std::runtime_error("hex digit");
        out.push_back((unsigned char)((hi << 4) | lo));
    }
    return out;
}

inline std::vector<unsigned char> build_image_bytes(
        const std::vector<Key>& starts, const std::vector<int>& hops,
        const std::vector<Layout>& nodes) {
    const size_t N = nodes.size();
    const size_t R = starts.size();
    if (N == 0) throw std::runtime_error("empty layout");
    std::vector<size_t> alloc(N), off(N);
    for (size_t i = 0; i < N; ++i) {
        const Layout& nd = nodes[i];
        const bool leaf = nd.children.empty();
        const int b = leaf ? 0 : (int)nd.children.size();
        const int K = leaf ? nd.span : (b - 1);
        const size_t used = 32 + 4 * (size_t)b +
                            (size_t)(K < 0 ? 0 : K) * (size_t)KW[nd.mode];
        alloc[i] = (used + 63) / 64 * 64;
        off[i] = i ? off[i - 1] + alloc[i - 1] : 64;
    }
    const size_t hopoff = off[N - 1] + alloc[N - 1];
    const size_t padded = (R * 4 + 63) / 64 * 64;
    const size_t total = hopoff + padded;
    std::vector<unsigned char> img(total, 0);
    std::memcpy(img.data(), "FIDX", 4);
    img[4] = 2;
    unsigned char* p = img.data();
    for (int k = 0; k < 4; ++k) p[8 + k] = (unsigned char)(R >> (8 * k));
    for (int k = 0; k < 4; ++k) p[12 + k] = (unsigned char)(N >> (8 * k));
    for (int k = 0; k < 4; ++k) p[16 + k] = (unsigned char)(hopoff >> (8 * k));
    for (int k = 0; k < 4; ++k) p[20 + k] = (unsigned char)(total >> (8 * k));
    for (size_t i = 0; i < N; ++i) {
        const Layout& nd = nodes[i];
        const bool leaf = nd.children.empty();
        const int b = leaf ? 0 : (int)nd.children.size();
        const int K = leaf ? nd.span : (b - 1);
        const size_t at = off[i];
        img[at] = (unsigned char)(leaf ? 1 : 0);
        img[at + 1] = (unsigned char)nd.mode;
        img[at + 2] = (unsigned char)nd.cached;
        img[at + 3] = 0;
        p[at + 4] = (unsigned char)nd.lo;
        p[at + 5] = (unsigned char)(nd.lo >> 8);
        p[at + 6] = (unsigned char)nd.span;
        p[at + 7] = (unsigned char)(nd.span >> 8);
        const unsigned cnt = (unsigned)(leaf ? nd.span : b);
        p[at + 8] = (unsigned char)cnt;
        p[at + 9] = (unsigned char)(cnt >> 8);
        p[at + 10] = 0;
        p[at + 11] = 0;
        for (int k = 0; k < 4; ++k) p[at + 12 + k] = (unsigned char)(alloc[i] >> (8 * k));
        const Key base = starts[nd.lo];
        for (int k = 0; k < 16; ++k) p[at + 16 + k] = (unsigned char)((base >> (8 * k)) & 0xff);
        size_t q = at + 32;
        if (!leaf) {
            for (size_t c = 0; c < nd.children.size(); ++c) {
                const unsigned v = (unsigned)off[nd.children[c]];
                for (int k = 0; k < 4; ++k) p[q + k] = (unsigned char)(v >> (8 * k));
                q += 4;
            }
        }
        const int w = KW[nd.mode];
        for (int k = 0; k < K; ++k) {
            const Key key = leaf ? starts[nd.lo + k]
                                 : starts[nodes[nd.children[k + 1]].lo];
            const Key val = nd.mode ? (key - base) : key;
            for (int t = 0; t < w; ++t) p[q + t] = (unsigned char)((val >> (8 * t)) & 0xff);
            q += (size_t)w;
        }
    }
    for (size_t k = 0; k < R; ++k) {
        const unsigned v = hops[k] < 0 ? 0xffffffffu : (unsigned)hops[k];
        for (int t = 0; t < 4; ++t) p[hopoff + 4 * k + t] = (unsigned char)(v >> (8 * t));
    }
    return img;
}

struct PackedNode {
    int kind, mode, cached, lo, span, count;
    unsigned allocated;
    Key base;
    std::vector<Key> keys;
    std::vector<unsigned> children;    // absolute byte offsets
};

struct PackedImage {
    unsigned R, count, hopoff, total;
    std::vector<int> hops;             // -1 means null
    std::map<unsigned, PackedNode> nodes;
};

inline PackedImage parse_image_bytes(const std::vector<unsigned char>& raw) {
    PackedImage im;
    if (raw.size() < 128 || raw.size() % 64) throw std::runtime_error("image size");
    if (std::memcmp(raw.data(), "FIDX", 4) || raw[4] != 2)
        throw std::runtime_error("image header");
    im.R = rd32(&raw[8]);
    im.count = rd32(&raw[12]);
    im.hopoff = rd32(&raw[16]);
    im.total = rd32(&raw[20]);
    if (im.total != raw.size()) throw std::runtime_error("image total");
    if (im.hopoff % 64 || im.hopoff <= 64 || im.hopoff > raw.size())
        throw std::runtime_error("hop offset");
    if (im.count < 1 || im.R < 1 || im.count > 2 * im.R - 1)
        throw std::runtime_error("node count");
    im.hops.resize(im.R);
    for (unsigned k = 0; k < im.R; ++k) {
        const unsigned x = rd32(&raw[im.hopoff + 4 * k]);
        im.hops[k] = (x == 0xffffffffu) ? -1 : (int)x;
    }
    unsigned off = 64;
    while (off < im.hopoff) {
        PackedNode n;
        if (off + 32 > im.hopoff) throw std::runtime_error("truncated node");
        n.kind = raw[off];
        n.mode = raw[off + 1];
        n.cached = raw[off + 2];
        n.lo = (int)rd16(&raw[off + 4]);
        n.span = (int)rd16(&raw[off + 6]);
        n.count = (int)rd16(&raw[off + 8]);
        n.allocated = rd32(&raw[off + 12]);
        if (n.kind != 0 && n.kind != 1) throw std::runtime_error("node kind");
        if (n.mode < 0 || n.mode > 2) throw std::runtime_error("node mode");
        const bool leaf = n.kind == 1;
        const int b = leaf ? 0 : n.count;
        const int K = leaf ? n.span : (n.count - 1);
        for (int k = 0; k < 16; ++k) n.base |= (Key)raw[off + 16 + k] << (8 * k);
        size_t q = off + 32;
        if (!leaf) {
            for (int c = 0; c < b; ++c) {
                n.children.push_back(rd32(&raw[q]));
                q += 4;
            }
        }
        const int w = KW[n.mode];
        for (int k = 0; k < K; ++k) {
            Key val = 0;
            for (int t = 0; t < w; ++t) val |= (Key)raw[q + t] << (8 * t);
            q += (size_t)w;
            n.keys.push_back(n.mode ? val + n.base : val);
        }
        im.nodes[off] = n;
        off += n.allocated;
    }
    if (off != im.hopoff) throw std::runtime_error("unaccounted node bytes");
    return im;
}

struct Answer {
    int hop, run;
    std::vector<unsigned> path;
};

// Predecessor search over the actual packed bytes: internal nodes select the
// child by the number of separator keys <= destination (equality goes right),
// leaves select the greatest stored start <= destination.
inline Answer image_lookup(const PackedImage& im, Key addr) {
    Answer res;
    res.hop = -1;
    res.run = -1;
    unsigned off = 64;
    while (true) {
        res.path.push_back(off);
        std::map<unsigned, PackedNode>::const_iterator it = im.nodes.find(off);
        if (it == im.nodes.end()) throw std::runtime_error("bad node offset");
        const PackedNode& n = it->second;
        int lo = 0, hi = (int)n.keys.size();
        while (lo < hi) {
            const int mid = (lo + hi) / 2;
            if (addr < n.keys[mid]) hi = mid; else lo = mid + 1;
        }
        if (n.kind == 1) {
            const int run = n.lo + lo - 1;
            if (run < n.lo || run >= n.lo + n.span || run < 0 ||
                run >= (int)im.R)
                throw std::runtime_error("leaf predecessor");
            res.run = run;
            res.hop = im.hops[run];
            return res;
        }
        if (lo >= (int)n.children.size()) throw std::runtime_error("child index");
        off = n.children[lo];
    }
}

struct PackedResult {
    std::string image;
    std::vector<Answer> answers;
};

inline PackedResult pack_image(const std::vector<Key>& starts,
                               const std::vector<int>& hops,
                               const std::vector<Layout>& nodes,
                               const std::vector<Key>& addresses) {
    PackedResult out;
    const std::vector<unsigned char> raw = build_image_bytes(starts, hops, nodes);
    const PackedImage im = parse_image_bytes(raw);
    out.image = bytes_hex(raw);
    for (size_t i = 0; i < addresses.size(); ++i)
        out.answers.push_back(image_lookup(im, addresses[i]));
    return out;
}

inline std::vector<Answer> trace_image(const std::string& image,
                                       const std::vector<Key>& addresses) {
    const std::vector<unsigned char> raw = hex_bytes(image);
    const PackedImage im = parse_image_bytes(raw);
    std::vector<Answer> out;
    for (size_t i = 0; i < addresses.size(); ++i)
        out.push_back(image_lookup(im, addresses[i]));
    return out;
}
