static void stage_atlas() {
    size_t n;
    std::cin >> n;
    std::vector<entry> fib;
    fib.reserve(n);
    for (size_t i = 0; i < n; ++i) {
        std::string s;
        int length, hop;
        std::cin >> s >> length >> hop;
        entry e;
