        VersionInput& vi = vers[v];
        std::cin >> vi.R;
        vi.starts.resize(vi.R);
        vi.hops.resize(vi.R);
        for (int k = 0; k < vi.R; ++k) {
            std::string s;
            int h;
            std::cin >> s >> h;
            vi.starts[k] = parse_key(s);
            vi.hops[k] = h;
        }
        int B;
        std::cin >> B;
        for (int t = 0; t < B; ++t) {
            long long rep;
            int m;
            std::cin >> rep >> m;
            std::vector<int> rs(m);
            for (int k = 0; k < m; ++k) std::cin >> rs[k];
            vi.bursts.push_back(std::make_pair(rep, rs));
        }
    }
    std::vector<VersionPlan> plans(V);
    for (int v = 0; v < V; ++v) plans[v] = plan_version(vers[v], C, hit, miss, dec);
    std::vector<std::vector<Cst> > D(V + 1, std::vector<Cst>(C + 1, CST_INF));
    std::vector<std::vector<int> > Par(V + 1, std::vector<int>(C + 1, -1));
    D[0][0] = 0;
    for (int v = 0; v < V; ++v)
        for (int r1 = 0; r1 <= C; ++r1) {
            if (D[v][r1] >= CST_INF) continue;
            for (int r2 = 0; r1 + r2 <= C; ++r2) {
                if (plans[v].cost[r2] >= CST_INF) continue;
                const Cst c = D[v][r1] + plans[v].cost[r2];
                if (c < D[v + 1][r1 + r2]) {
                    D[v + 1][r1 + r2] = c;
                    Par[v + 1][r1 + r2] = r1;
                }
            }
        }
    int best = 0;
    for (int r = 1; r <= C; ++r)
        if (D[V][r] < D[V][best]) best = r;
    std::vector<int> choice(V, 0);
    {
        int r = best;
        for (int v = V; v >= 1; --v) {
            choice[v - 1] = r - Par[v][r];
            r = Par[v][r];
        }
    }
    for (int v = 0; v < V; ++v) {
        const std::vector<Layout>& nodes = plans[v].layouts[choice[v]];
        std::cout << nodes.size() << '\n';
        for (size_t i = 0; i < nodes.size(); ++i) {
            const Layout& nd = nodes[i];
            std::cout << nd.lo << ' ' << nd.span << ' ' << nd.mode << ' '
                      << nd.cached << ' ' << nd.children.size();
            for (size_t c = 0; c < nd.children.size(); ++c)
                std::cout << ' ' << nd.children[c];
            std::cout << '\n';
        }
    }
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(0);
    try {
        std::string command;
        if (!(std::cin >> command)) throw std::runtime_error("native command");
        if (command == "ATLAS") stage_atlas();
        else if (command == "PACK") stage_pack();
        else if (command == "TRACE") stage_trace();
        else if (command == "PLAN") stage_plan();
        else throw std::runtime_error("unknown native command");
        if (!std::cin.eof()) {
            std::string rest;
            if (std::cin >> rest) throw std::runtime_error("trailing native input");
        }
    } catch (const std::exception& e) {
        std::cerr << e.what() << '\n';
        return 1;
    }
    return 0;
}
