sys.path.insert(0,'/workspace'); sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/workspace/tmp/tests')
import test_optimal as T
from reference import reference_runs, text_of, U

def build(rng, npref, spaced=True, with_default=True):
    """npref non-overlapping /64 (or /96) prefixes -> 2*npref+1 runs."""
    routes=[]
    if with_default: routes.append(["::/0", rng.randrange(1,20)])
    shift = 64
    for k in range(npref):
        start = (rng.randrange(1, 1<<8) << shift) if False else ((k+1)*(4 if spaced else 1))<<shift
        routes.append([text_of(start)+"/64", rng.randrange(1,20)])
    return routes

def check_case(case, label):
    payload=json.dumps({'cases':[case]})
    try:
        T.check(payload, True)
        print('ok',label, flush=True)
    except AssertionError as e:
        print('FAIL',label,e); print(payload)
    except Exception as e:
        print('ERR',label,type(e).__name__,e)

rng=random.Random(2024)
for npref in (4,5):
    for t in range(4):
        routes=build(rng,npref)
        hists=[]
        fib={}
        # parse to normalized
        from protocol import prefix
        d={}
        for p,h in routes:
            d[prefix(p)]=h
        hists=[dict(d)]
        txs=[]
        for _ in range(1):
            tx=[]
            for _ in range(rng.randrange(1,4)):
                k=rng.randrange(1,npref+1)
                start=((k)*(4))<<64
                if rng.random()<0.5:
                    hop=rng.randrange(1,20)
                    tx.append(['set',text_of(start)+"/64",hop]); d[(start,64)]=hop
                else:
                    tx.append(['erase',text_of(start)+"/64"]); d.pop((start,64),None)
            txs.append(tx); hists.append(dict(d))
        bursts=[]
        for vi in range(len(hists)):
            starts,hops=reference_runs(hists[vi])
            addrs=[]
            for _ in range(rng.randrange(1,6)):
                pick=rng.random()
                if pick<0.5: addrs.append(text_of(rng.choice(starts)))
                elif pick<0.75: addrs.append(text_of((rng.choice(starts)+rng.randrange(0,3))%U))
                else: addrs.append(text_of(rng.randrange(0,U)))
            bursts.append({'version':vi,'repeat':rng.choice([1,4,50]),'addresses':addrs})
        hit=rng.randrange(1,10)
        case={'initial':routes,'transactions':txs,'bursts':bursts,
              'cache_pages':rng.randrange(0,6),
              'costs':{'hit':hit,'miss':min(256,hit+rng.randrange(1,60)),
                       'decode':[rng.randrange(0,6) for _ in range(3)]}}
        check_case(case,'npref=%d t=%d R=%s'%(npref,t,[len(reference_runs(v)[0]) for v in hists]))
